  const out = [];
  for (const [name, html] of Object.entries(SITES)) {
    const rec = { name };
    let g; try { g = await cloudflare.request({ method: 'GET', path: `/accounts/${accountId}/pages/projects/${name}` }); } catch (e) { g = { success: false }; }
    if (!g.success) {
      let c; try { c = await cloudflare.request({ method: 'POST', path: `/accounts/${accountId}/pages/projects`, body: { name, production_branch: 'main' } }); } catch (e) { c = { success: false, errors: String(e) }; }
      rec.created = c.success; if (!c.success) { rec.error = c.errors; out.push(rec); continue; }
      rec.subdomain = c.result?.subdomain;
    } else rec.subdomain = g.result?.subdomain;
    const worker = `const HTML = ${JSON.stringify(html)};
export default { async fetch(request) {
  if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Method not allowed', { status: 405 });
  const p = new URL(request.url).pathname;
  if (p === '/robots.txt') return new Response('User-agent: *\\nDisallow: /\\n', { headers: { 'content-type': 'text/plain', 'x-robots-tag': 'noindex, nofollow' } });
  return new Response(HTML, { headers: { 'content-type': 'text/html; charset=utf-8', 'x-robots-tag': 'noindex, nofollow', 'cache-control': 'public, max-age=300' } });
} };`;
    const b = 'SF' + Date.now() + Math.random().toString(36).slice(2);
    const part = (n, ct, d, fn) => [`--${b}`, `Content-Disposition: form-data; name="${n}"` + (fn ? `; filename="${fn}"` : ''), `Content-Type: ${ct}`, '', d].join('\r\n');
    const body = [part('manifest', 'application/json', '{}'), part('branch', 'text/plain', 'main'), part('_worker.js', 'application/javascript+module', worker, '_worker.js'), `--${b}--`, ''].join('\r\n');
    let r; try { r = await cloudflare.request({ method: 'POST', path: `/accounts/${accountId}/pages/projects/${name}/deployments`, body, contentType: `multipart/form-data; boundary=${b}`, rawBody: true }); } catch (e) { r = { success: false, errors: String(e) }; }
    rec.deploy_ok = r.success; rec.url = r.result?.url; rec.stage = r.result?.latest_stage?.status; if (!r.success) rec.error = r.errors;
    out.push(rec);
  }
  return out;
